package com.dts.practice.simulation;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.dts.practice.simulation.SimulationExamModel.*;

@Testcontainers
class SimulationPresetPostgresTest {
    @Container static final PostgreSQLContainer<?> pg=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("dts_practice");
    static JdbcTemplate jdbc;static TransactionTemplate tx;
    final UUID user=UUID.randomUUID();final SimulationBank.Snapshot bank=SimulationFixtures.published().snapshot();final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
    final AtomicReference<Instant> now=new AtomicReference<>(Instant.parse("2026-11-03T00:00:00Z"));
    List<SimulationPresets.Version> versions;SimulationExamRepository repo;SimulationExamService exams;SimulationPresetService presets;SimulationExamAccess access;SimulationBankClient banks;SimulationExamMediaClient media;SimulationExamRules rules;Map<String,String> protectedBefore;
    @BeforeAll static void migrate(){var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("33").load().migrate();}
    static Map<String,String> protectedRows(){var map=new TreeMap<String,String>();for(String table:jdbc.queryForList("SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename NOT LIKE 'simulation_exam_%' AND tablename<>'flyway_schema_history'",String.class)){assertTrue(table.matches("[a-z_]+"));map.put(table,jdbc.queryForObject("SELECT count(*)::text||':'||md5(coalesce(string_agg(to_jsonb(t)::text,E'\\n' ORDER BY to_jsonb(t)::text),'')) FROM "+table+" t",String.class));}return map;}
    @BeforeEach void setup(){
        versions=new ArrayList<>(SimulationPresetFixtures.catalogue(bank).items());repo=new SimulationExamRepository(jdbc,json);access=mock(SimulationExamAccess.class);banks=mock(SimulationBankClient.class);media=mock(SimulationExamMediaClient.class);rules=spy(new SimulationExamRules());
        when(access.require(anyBoolean())).thenReturn(new SimulationAccess.Actor(user,"fixture-access"));when(banks.current()).thenReturn(bank);
        when(banks.presets()).thenAnswer(x->new SimulationPresets.Catalog(bank.bankVersion(),bank.manifestSha256(),List.copyOf(versions)));
        when(banks.preset(any())).thenAnswer(x->versions.stream().filter(v->v.presetVersionId().equals(x.getArgument(0))).findFirst().orElseThrow(SimulationExamFailure::missing));
        when(media.eligibility(any(),any(),any())).thenAnswer(x->{List<SimulationBank.Scenario> list=x.getArgument(2);return list.stream().map(s->new SimulationExamMediaClient.Eligible(s.videoMediaId(),true,s.durationMs(),s.video().videoTrackDurationMs(),"fixtureetag","READY")).toList();});
        when(media.playback(any(),any(),any(),anyBoolean())).thenAnswer(x->{Row r=x.getArgument(1);Frame f=x.getArgument(2);boolean review=x.getArgument(3);return new SimulationExamMediaClient.Video(r.id,f.position,f.playbackId,r.bank,r.manifest,f.snapshot.videoMediaId(),"http://localhost:9000/media/fixture.mp4?fixture=only",OffsetDateTime.now().plusSeconds(300),"video/mp4",f.duration,review?"REVIEW":"CURRENT");});
        var clock=mock(SimulationLearningClock.class);when(clock.now()).thenAnswer(x->now.get());exams=new SimulationExamService(access,banks,repo,media,rules,clock);presets=new SimulationPresetService(access,banks,repo,clock);protectedBefore=protectedRows();
    }
    @AfterEach void protectedDomainsUnchanged(){assertEquals(protectedBefore,protectedRows());}
    <T>T call(Supplier<T> a){return tx.execute(s->a.get());}
    Create request(int set){var v=versions.get(set-1);return new Create("PRESET","B",null,v.presetSetId(),v.presetVersionId());}
    Session create(){return call(()->exams.create(UUID.randomUUID(),request(1)));}
    Event event(Session s,int ms){return new Event(UUID.randomUUID(),s.currentPosition(),s.playbackEventId(),ms);}
    Session start(Session s){call(()->exams.playback(s.sessionId(),"B"));return call(()->exams.start(s.sessionId(),event(s,0),"B"));}
    Session finish(Session initial,Integer response){
        var s=start(initial);Instant base=now.get();int duration=repo.frame(s.sessionId(),s.currentPosition()).duration;
        if(response!=null&&response==0)call(()->exams.reaction(s.sessionId(),event(s,0),"B"));
        for(int current=0;current<duration;){int next=Math.min(duration,current+3000);if(response!=null&&response>current&&response<=next){now.set(base.plusMillis(response));call(()->exams.reaction(s.sessionId(),event(s,response),"B"));}now.set(base.plusMillis(next));int ms=next;if(next==duration)return call(()->exams.complete(s.sessionId(),event(s,ms),"B"));call(()->exams.heartbeat(s.sessionId(),event(s,ms),"B"));current=next;}
        throw new AssertionError();
    }
    Session ready(Session s,int total){int left=total;for(int i=0;i<10;i++){int points=Math.min(5,left);left-=points;s=finish(s,points==0?null:15000-points*1000);}return s;}
    Session done(int total){var s=ready(create(),total);return call(()->exams.submit(s.sessionId(),new Command(UUID.randomUUID()),"B"));}
    SimulationPresets.Item item(){return call(()->presets.list("B")).items().getFirst();}
    int count(){return jdbc.queryForObject("SELECT count(*) FROM simulation_exam_sessions WHERE user_id=?",Integer.class,user);}
    String stored(UUID id){return jdbc.queryForObject("SELECT result_json::text FROM simulation_exam_results WHERE session_id=?",String.class,id);}
    void cancel(Session s){call(()->exams.cancel(s.sessionId(),new Command(UUID.randomUUID()),"B"));}

    @Test void listAndDetailReadNeverCreateSessionsOrExposePrivateSource()throws Exception{
        var list=call(()->presets.list("B"));assertEquals(15,list.totalPublishedSets());assertEquals(0,count());var detail=call(()->presets.detail(list.items().getFirst().presetSetId(),"B"));assertTrue(detail.canStart());assertEquals(0,count());
        String body=json.writeValueAsString(detail);for(String key:List.of("scenarioId","scenarioNumber","scoringTimeline","hazardSign","recognitionTip","videoMediaId","thumbnailMediaId","accessToken","ticket"))assertFalse(body.contains("\""+key+"\""),key);
    }
    @Test void exactTenFixedPositionsRemainOrderedAcrossReloadAndCreateRetry(){UUID key=UUID.randomUUID();var request=request(1);var s=call(()->exams.create(key,request));assertEquals("PRESET",s.mode());assertEquals(request.presetVersionId(),s.presetVersionId());assertEquals(s,call(()->exams.create(key,request)));assertEquals(s,call(()->exams.get(s.sessionId(),"B")));assertEquals(Arrays.stream(SimulationPresetFixtures.ORDERS[0]).boxed().toList(),repo.frames(s.sessionId()).stream().map(f->f.snapshot.scenarioNumber()).toList());verify(rules,never()).shuffled(any());assertEquals(1,count());}
    @Test void sameCreateKeyWithDifferentPresetIsConflict(){UUID key=UUID.randomUUID();call(()->exams.create(key,request(1)));assertEquals("SIMULATION_EXAM_EVENT_CONFLICT",assertThrows(SimulationExamFailure.class,()->call(()->exams.create(key,request(2)))).code);assertEquals(1,count());}
    @Test void randomPresetAndAllLicenseClassesShareOneActiveSlot(){var random=call(()->exams.create(UUID.randomUUID(),new Create("RANDOM","CE",null)));var error=assertThrows(SimulationExamFailure.class,this::create);assertEquals(random.sessionId(),error.activeSessionId);assertFalse(call(()->presets.detail(versions.getFirst().presetSetId(),"B")).canStart());cancel(random);var s=create();assertEquals(s.sessionId(),assertThrows(SimulationExamFailure.class,()->call(()->exams.create(UUID.randomUUID(),new Create("RANDOM","CE",null)))).activeSessionId);}
    @Test void oneUnreadyFixedVideoRollsBackWithoutSubstitution(){doAnswer(x->{List<SimulationBank.Scenario> list=x.getArgument(2);return list.stream().map(s->new SimulationExamMediaClient.Eligible(s.videoMediaId(),s!=list.getFirst(),s.durationMs(),s.video().videoTrackDurationMs(),s==list.getFirst()?null:"fixtureetag",s==list.getFirst()?"NOT_READY":"READY")).toList();}).when(media).eligibility(any(),any(),any());assertEquals("SIMULATION_PRESET_MEDIA_UNAVAILABLE",assertThrows(SimulationExamFailure.class,this::create).code);assertEquals(0,count());verify(rules,never()).shuffled(any());}
    @Test void wrongSetVersionBindingCannotCreateSession(){var a=versions.getFirst();var b=versions.get(1);assertThrows(SimulationExamFailure.class,()->call(()->exams.create(UUID.randomUUID(),new Create("PRESET","B",null,a.presetSetId(),b.presetVersionId()))));assertEquals(0,count());}
    @Test void archivedBeforeCommitIsRejectedAndPreviousCreateRetryStillWorks(){var s=create();var key=repo.get(user,s.sessionId(),false).createKey;versions.clear();assertEquals(s,call(()->exams.create(key,new Create("PRESET","B",null,s.presetSetId(),s.presetVersionId()))));cancel(s);assertThrows(SimulationExamFailure.class,()->call(()->exams.create(UUID.randomUUID(),new Create("PRESET","B",null,s.presetSetId(),s.presetVersionId()))));}
    @Test void publicationChangesDuringEligibilityLeaveNoLocalSession(){var selected=versions.getFirst();when(banks.preset(selected.presetVersionId())).thenReturn(selected).thenThrow(SimulationExamFailure.missing());assertThrows(SimulationExamFailure.class,this::create);assertEquals(0,count());}
    @ParameterizedTest @CsvSource({"34,false,FAILED","35,true,PASSED","50,true,PASSED","0,false,FAILED"})void sharedEngineScoresPinnedPresetAndBoundary(int score,boolean passed,String label){var s=done(score);var r=call(()->exams.result(s.sessionId(),"B"));assertEquals("PRESET",r.mode());assertEquals(s.preset(),r.preset());assertEquals(score,r.totalScore());assertEquals(35,r.passingScore());assertEquals(passed,r.passed());assertEquals(label,r.resultStatus());assertEquals(10,r.items().size());assertEquals(score,r.items().stream().mapToInt(ResultItem::score).sum());}
    @Test void latestCompletedIsThirtyAfterFortyFiveAndOldResultIsRetained(){var first=done(45);String old=stored(first.sessionId());var second=done(30);var latest=item();assertEquals(second.sessionId(),latest.latestCompletedSessionId());assertEquals(30,latest.latestCompletedScore());assertFalse(latest.latestCompletedPassed());assertEquals(old,stored(first.sessionId()));assertEquals(45,call(()->exams.result(first.sessionId(),"B")).totalScore());}
    @Test void retakeKeepsPriorCompletedResultAndCancelDoesNotReplaceIt(){var completed=done(35);var retake=create();var view=item();assertEquals(retake.sessionId(),view.activeSessionId());assertEquals(completed.sessionId(),view.latestCompletedSessionId());assertEquals("IN_PROGRESS",view.attemptStatus());cancel(retake);var after=item();assertNull(after.activeSessionId());assertEquals(completed.sessionId(),after.latestCompletedSessionId());assertEquals("PASSED",after.attemptStatus());}
    @Test void newPublishedVersionHasNoInheritedGradeButOldHistoryStillReviews(){var old=done(50);String frozen=stored(old.sessionId());versions.set(0,SimulationPresetFixtures.version(bank,1,"v2"));var item=item();assertFalse(item.hasCompletedAttempt());assertNull(item.latestCompletedSessionId());assertNull(item.latestCompletedScore());assertEquals(10,call(()->exams.review(old.sessionId(),"B")).items().size());assertEquals(frozen,stored(old.sessionId()));}
    @Test void reviewResultAndPlaybackAreReadOnlyAndIndependentOfCurrentSource(){var old=done(35);String frozen=stored(old.sessionId());String frames=jdbc.queryForObject("SELECT jsonb_agg(to_jsonb(p) ORDER BY position)::text FROM simulation_exam_positions p WHERE session_id=?",String.class,old.sessionId());versions.clear();when(banks.current()).thenThrow(SimulationFailure.unavailable());var r=call(()->exams.review(old.sessionId(),"CE"));assertEquals(old.preset(),r.result().preset());assertEquals(Arrays.stream(SimulationPresetFixtures.ORDERS[0]).boxed().toList(),r.items().stream().map(ReviewItem::scenarioNumber).toList());call(()->exams.reviewPlayback(old.sessionId(),1,"B"));assertEquals(frozen,stored(old.sessionId()));assertEquals(frames,jdbc.queryForObject("SELECT jsonb_agg(to_jsonb(p) ORDER BY position)::text FROM simulation_exam_positions p WHERE session_id=?",String.class,old.sessionId()));}
    @Test void separateActorCannotReadOrMutateAnotherPresetExam(){var s=create();when(access.require(anyBoolean())).thenReturn(new SimulationAccess.Actor(UUID.randomUUID(),"other"));assertThrows(SimulationExamFailure.class,()->call(()->exams.get(s.sessionId(),"B")));assertThrows(SimulationExamFailure.class,()->call(()->exams.cancel(s.sessionId(),new Command(UUID.randomUUID()),"B")));assertFalse(call(()->presets.list("B")).items().getFirst().hasCompletedAttempt());assertNull(call(()->presets.list("B")).activeSession());}
    @Test void restartReceiptKeepsFirstReactionAndPresetMetadataAfterReload(){var s=start(create());now.set(now.get().plusSeconds(10));var reacted=call(()->exams.reaction(s.sessionId(),event(s,10000),"B"));var request=new Restart(UUID.randomUUID(),1,reacted.playbackEventId());var restarted=call(()->exams.restart(s.sessionId(),request,"B"));assertEquals(restarted,call(()->exams.restart(s.sessionId(),request,"B")));assertEquals(s.preset(),restarted.preset());assertTrue(restarted.responseRecorded());assertNotEquals(s.playbackEventId(),restarted.playbackEventId());assertThrows(SimulationExamFailure.class,()->call(()->exams.start(s.sessionId(),event(s,0),"B")));assertEquals(restarted,call(()->exams.get(s.sessionId(),"B")));}
    @Test void databaseRejectsPresetSnapshotMutationAndRandomModeSpoof(){var s=create();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE simulation_exam_sessions SET preset_version_id=? WHERE id=?",UUID.randomUUID(),s.sessionId()));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE simulation_exam_sessions SET mode='RANDOM' WHERE id=?",s.sessionId()));assertEquals(s,call(()->exams.get(s.sessionId(),"B")));}
    @Test void sameKeyConcurrentCreateConvergesToOnePresetSession()throws Exception{UUID key=UUID.randomUUID();var request=request(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->call(()->exams.create(key,request)));var b=pool.submit(()->call(()->exams.create(key,request)));assertEquals(a.get(30,TimeUnit.SECONDS).sessionId(),b.get(30,TimeUnit.SECONDS).sessionId());assertEquals(1,count());}finally{pool.shutdownNow();}}
    @Test void oldRandomReceiptsAndResultsKeepTheirOriginalWireShape()throws Exception{var random=call(()->exams.create(UUID.randomUUID(),new Create("RANDOM","B",null)));String wire=repo.encode(random);assertFalse(wire.contains("\"preset\""));assertFalse(wire.contains("\"presetSetId\""));assertEquals(random,repo.decode(wire,Session.class));var ready=ready(random,35);var completed=call(()->exams.submit(ready.sessionId(),new Command(UUID.randomUUID()),"B"));var result=call(()->exams.result(completed.sessionId(),"B"));String resultWire=repo.encode(result);assertFalse(resultWire.contains("\"preset\""));assertEquals(result,repo.decode(resultWire,Result.class));}
    @Test void presetReceiptsAndResultsRoundTripAllMetadata()throws Exception{var completed=done(35);var result=call(()->exams.result(completed.sessionId(),"B"));assertEquals(completed,repo.decode(repo.encode(completed),Session.class));assertEquals(result,repo.decode(repo.encode(result),Result.class));assertEquals(completed.presetVersionId(),json.readTree(repo.encode(result)).path("presetVersionId").isMissingNode()?null:UUID.fromString(json.readTree(repo.encode(result)).path("presetVersionId").asText()));}
    @Test void emptyCatalogueAndUnknownSetRemainReadOnly(){versions.clear();assertTrue(call(()->presets.list("B")).items().isEmpty());assertThrows(SimulationExamFailure.class,()->call(()->presets.detail(UUID.randomUUID(),"B")));assertEquals(0,count());}
    @Test void readyToSubmitStillBlocksRetakeAndCannotLeakResultBeforeSubmission(){var ready=ready(create(),35);assertEquals("READY_TO_SUBMIT",ready.status());assertEquals(ready.sessionId(),item().activeSessionId());assertFalse(item().hasCompletedAttempt());assertThrows(SimulationExamFailure.class,this::create);assertThrows(SimulationExamFailure.class,()->call(()->exams.result(ready.sessionId(),"B")));}
    @Test void completedGradesAndReviewAreStrictlyOwned(){var own=done(35);when(access.require(anyBoolean())).thenReturn(new SimulationAccess.Actor(UUID.randomUUID(),"other"));assertFalse(item().hasCompletedAttempt());assertNull(item().latestCompletedSessionId());assertThrows(SimulationExamFailure.class,()->call(()->exams.result(own.sessionId(),"B")));assertThrows(SimulationExamFailure.class,()->call(()->exams.review(own.sessionId(),"B")));assertThrows(SimulationExamFailure.class,()->call(()->exams.reviewPlayback(own.sessionId(),1,"B")));}
    @Test void olderActiveEditionIsResumableWithoutBeingRelabelledAsCurrent(){var old=create();versions.set(0,SimulationPresetFixtures.version(bank,1,"v2"));var list=call(()->presets.list("B"));assertNull(list.items().getFirst().activeSessionId());assertEquals(old.sessionId(),list.activeSession().sessionId());assertEquals(old.presetVersionId(),list.activeSession().presetVersionId());assertFalse(call(()->presets.detail(old.presetSetId(),"B")).canStart());assertEquals(old.presetVersionId(),call(()->exams.get(old.sessionId(),"B")).presetVersionId());}
    @Test void listAndDetailRunUnderPostgresReadOnlySnapshotWithExistingHistory(){var previous=done(35);var retake=create();String saved=stored(previous.sessionId());var readonly=new TransactionTemplate(tx.getTransactionManager());readonly.setReadOnly(true);readonly.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);readonly.execute(s->{assertEquals("on",jdbc.queryForObject("SELECT current_setting('transaction_read_only')",String.class));var list=presets.list("B");assertEquals(previous.sessionId(),list.items().getFirst().latestCompletedSessionId());assertEquals(retake.sessionId(),list.activeSession().sessionId());assertFalse(presets.detail(previous.presetSetId(),"B").canStart());return null;});assertEquals(saved,stored(previous.sessionId()));assertEquals(2,count());}
    @Test void midInsertFailureRollsBackSessionAndAllPositions(){jdbc.execute("CREATE FUNCTION simulation_preset_test_abort() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'fixture insertion failure'; END; $$");jdbc.execute("CREATE TRIGGER simulation_preset_test_abort BEFORE INSERT ON simulation_exam_positions FOR EACH ROW WHEN (NEW.position=5) EXECUTE FUNCTION simulation_preset_test_abort()");try{assertThrows(org.springframework.dao.DataAccessException.class,this::create);assertEquals(0,count());}finally{jdbc.execute("DROP TRIGGER simulation_preset_test_abort ON simulation_exam_positions");jdbc.execute("DROP FUNCTION simulation_preset_test_abort()");}}
}
